import{_ as a,C as r,c as s,o as i,a3 as t,G as n}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Bill of materials","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/manufacturing/basic-setup/bill-of-materials.md","filePath":"master/supply-chain/manufacturing/basic-setup/bill-of-materials.md","lastUpdated":1793074831000}'),l={name:"master/supply-chain/manufacturing/basic-setup/bill-of-materials.md"};function g(u,e,d,m,h,p){const o=r("ImagePopup");return i(),s("div",null,[e[0]||(e[0]=t('<h1 id="bill-of-materials" tabindex="-1">Bill of materials <a class="header-anchor" href="#bill-of-materials" aria-label="Permalink to &quot;Bill of materials&quot;">​</a></h1><p>A bill of materials (BoM) is the recipe of a finished product. It lists the components for one batch, the quantity it makes and, with <strong>Work Orders</strong> on, the operations. Every manufacturing order copies its components and work orders from the BoM.</p><blockquote><p><strong>In simple words:</strong> A BoM says what goes in, in what amount, and which steps make the product.</p></blockquote><p>Open it from <code>Manufacturing → Products → Bills of Materials</code>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>The <strong>Operations</strong> tab appears only when <strong>Work Orders</strong> is on. The setting is in <code>Manufacturing → Settings → Manage Operations</code>. See <a href="./../get-started/manufacturing-settings.html">Manufacturing settings</a>.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The list has the tabs <strong>All</strong> and <strong>Archived</strong>. Columns are <strong>Reference</strong>, <strong>Product</strong>, <strong>Quantity</strong>, <strong>UOM</strong> and <strong>Company</strong>.</p>',8)),n(o,{src:"/images1/manufacturing/bom_list.png",alt:"Bills of Materials list with BOM-MC-LAPTOP row and the New Bill of Material button"}),e[1]||(e[1]=t('<h2 id="create-a-bill-of-materials" tabindex="-1">Create a bill of materials <a class="header-anchor" href="#create-a-bill-of-materials" aria-label="Permalink to &quot;Create a bill of materials&quot;">​</a></h2><ol><li>Go to <code>Manufacturing → Products → Bills of Materials</code>.</li><li>Click <strong>New Bill of Material</strong>.</li><li>Fill the <strong>General</strong> box, then the tabs and <strong>Miscellaneous</strong> box below.</li><li>Click <strong>Create</strong>. Use <strong>Create &amp; create another</strong> to keep going.</li></ol><h3 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h3><ul><li><strong><em>Product:</em></strong> Required. The finished product, for example <strong>Business Laptop</strong>.</li><li><strong><em>Product Variant:</em></strong> Pick one variant, or leave empty to cover all variants.</li><li><strong><em>Quantity:</em></strong> Required. How many units this recipe makes, usually 1.</li><li><strong><em>UOM:</em></strong> Unit of the quantity.</li><li><strong><em>Reference:</em></strong> A code such as <strong>BOM-MC-LAPTOP</strong>. Useful when a product has several BoMs.</li><li><strong><em>Company:</em></strong> Required. The company that owns the BoM.</li></ul>',4)),n(o,{src:"/images1/manufacturing/bom_general.png",alt:"New BoM form General box filled for Business Laptop, quantity 1, Units, reference BOM-MC-LAPTOP"}),e[2]||(e[2]=t('<h3 id="components-tab" tabindex="-1">Components tab <a class="header-anchor" href="#components-tab" aria-label="Permalink to &quot;Components tab&quot;">​</a></h3><p>Click <strong>Add a line</strong> for each part.</p><ul><li><strong><em>Component:</em></strong> Required. The product you consume.</li><li><strong><em>Quantity:</em></strong> Required. Amount needed for one batch. RAM 16GB is 2 for one laptop.</li><li><strong><em>Product Unit of Measure:</em></strong> Required. Unit of the component.</li><li><strong><em>Apply on Variants:</em></strong> Optional column. Limit the line to some variants. See <a href="./../advanced-configuration/bom-variants.html">BoM variants</a>.</li><li><strong><em>Consumed in Operation:</em></strong> Optional column. Choose the operation that uses the part.</li><li><strong><em>Highlight Consumption:</em></strong> Optional column. Marks a key component.</li></ul>',3)),n(o,{src:"/images1/manufacturing/bom_components.png",alt:"Components tab with the six Business Laptop components and quantities"}),e[3]||(e[3]=t('<h3 id="operations-tab" tabindex="-1">Operations tab <a class="header-anchor" href="#operations-tab" aria-label="Permalink to &quot;Operations tab&quot;">​</a></h3><p>Shown when <strong>Work Orders</strong> is on. Each line becomes a work order on the manufacturing order.</p><ul><li><strong><em>Operation:</em></strong> The step, such as <strong>Assemble Components</strong>.</li><li><strong><em>Work Center:</em></strong> Where it runs, such as Assembly Station.</li><li><strong><em>Duration Computation:</em></strong> Compute from tracked time or set it manually.</li><li><strong><em>Computed on last:</em></strong> Number of past work orders used for the average.</li><li><strong><em>Company</em></strong>, <strong><em>Apply on Variants</em></strong>, <strong><em>Duration (minutes)</em>:</strong> Company, variant limit and the planned time.</li></ul><p>Use <strong>Add a line</strong> for a new step, <strong>Edit Operation</strong> to open the full form, or <strong>Copy Existing Operations</strong> to reuse steps from another BoM. See <a href="./../advanced-configuration/operations.html">Operations</a>.</p>',4)),n(o,{src:"/images1/manufacturing/bom_operations.png",alt:"Operations tab with Assemble Components (Assembly Station) and Test & Pack (Quality & Packing)"}),e[4]||(e[4]=t('<h2 id="miscellaneous-box" tabindex="-1">Miscellaneous box <a class="header-anchor" href="#miscellaneous-box" aria-label="Permalink to &quot;Miscellaneous box&quot;">​</a></h2><ul><li><strong><em>Manufacturing Readiness:</em></strong> Required. <strong>When all components are available</strong> or <strong>When components for first operation are available</strong>. It decides when the order shows <strong>Ready</strong>.</li><li><strong><em>Routing:</em></strong> The operation type used for the order.</li><li><strong><em>Flexible Consumption:</em></strong> Required. <strong>Allowed</strong>, <strong>Allowed with warning</strong> or <strong>Blocked</strong>. New BoMs start on <strong>Allowed with warning</strong>. See below.</li><li><strong><em>Manufacturing Lead Time:</em></strong> Required. Days needed to build.</li><li><strong><em>Days to prepare Manufacturing Order:</em></strong> Required. Days of preparation before production.</li></ul>',2)),n(o,{src:"/images1/manufacturing/bom_miscellaneous.png",alt:"Miscellaneous box with Flexible Consumption and readiness options visible"}),e[5]||(e[5]=t('<h3 id="flexible-consumption" tabindex="-1">Flexible Consumption <a class="header-anchor" href="#flexible-consumption" aria-label="Permalink to &quot;Flexible Consumption&quot;">​</a></h3><p>It controls what happens when operators use other quantities than planned.</p><table tabindex="0"><thead><tr><th>Choice</th><th>Result at Produce</th></tr></thead><tbody><tr><td><strong>Allowed</strong></td><td>No question asked</td></tr><tr><td><strong>Allowed with warning</strong></td><td>The <strong>Consumption Warning</strong> window appears</td></tr><tr><td><strong>Blocked</strong></td><td>The same window appears</td></tr></tbody></table><p>See <a href="./../workflows/produce-and-consume.html">Produce and consume</a>.</p><h2 id="bom-overview" tabindex="-1">BoM Overview <a class="header-anchor" href="#bom-overview" aria-label="Permalink to &quot;BoM Overview&quot;">​</a></h2><p>Open a BoM and click <strong>Overview</strong>. Choose <strong>Quantity</strong> and <strong>Variant</strong> filters. The page shows <strong>Free to Use</strong>, <strong>On Hand</strong> and <strong>Total Cost</strong>. The table lists each component with <strong>Quantity</strong>, <strong>Lead Time</strong>, <strong>Route</strong>, <strong>BoM Cost</strong> and <strong>Product Cost</strong>, plus operation minutes. The unit cost depends on current product costs. A worked cost example is on <a href="./manufacturing-order-costs.html">Manufacturing order costs</a>.</p>',6)),n(o,{src:"/images1/manufacturing/bom_overview.png",alt:"BoM Overview page for BOM-MC-LAPTOP showing components, Operations rows and Unit Cost"}),e[6]||(e[6]=t('<h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><ul><li><strong>View</strong>, <strong>Edit</strong> and <strong>Overview</strong> are the sub tabs of a BoM.</li><li>Deleting a BoM archives it. Open the <strong>Archived</strong> tab to find it.</li></ul><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><p>When you create an order, Aureus scales the component quantities to the order quantity. It also adds one work order per BoM operation.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./configure-product.html">Configure a product</a></li><li><a href="./manufacturing-order-costs.html">Manufacturing order costs</a></li><li><a href="./../advanced-configuration/work-order-dependencies.html">Work order dependencies</a></li><li><a href="./../workflows/manufacturing-orders.html">Manufacturing orders</a></li></ul>',6))])}const b=a(l,[["render",g]]);export{f as __pageData,b as default};
